INSERT INTO `questions` (`id`, `category_id`, `image_path`, `prompt`, `answer_text`, `explanation`, `time_limit_seconds`, `created_at`, `updated_at`) VALUES
(1, 1, 'questions/simson.jpg', 'Siapakah nama tokoh yang telah mengalahkan singa dengan mudah dan menjadi hakim atas bangsa yahudi ?', 'Simson', 'Simson yang dipanggil Allah menjadi hakim dan mempunyai kekuatan super.', 16, '2025-12-23 21:50:45', '2025-12-23 21:50:45'),
(2, 1, 'questions/yesus.jpg', 'Tuhan Yesus berpuasa di padang gurun selama ?', '40 hari', 'Yesus berpuasa selama 40 Hari di padang gurun tanpa makan dan minum.', 16, '2025-12-23 21:50:45', '2025-12-23 21:50:45'),
(3, 1, 'questions/daud.jpg', 'Siapa yang menuliskan kitab mazmur ?', 'Daud', 'Daud menulis kitab mazmur yang mencerminkan kehidupan nya.', 16, '2025-12-23 21:50:45', '2025-12-23 21:50:45'),
(4, 1, 'questions/elia.jpg', 'Siapakah yang telah diangkat Tuhan dengan menggunakan kereta berapi ?', 'Elia', 'Elia berfirman kepada elisa bahwa akan diangkat Tuhan.', 16, '2025-12-23 21:50:45', '2025-12-23 21:50:45'),
(5, 1, 'questions/daniel.jpg', 'Siapakah nama tokoh berikut yang berpuasa dengan tidak memakan daging ?', 'Daniel', 'Elia berfirman kepada elisa bahwa akan diangkat Tuhan.', 16, '2025-12-23 21:50:45', '2025-12-23 21:50:45'),
(6, 1, 'questions/gandum.jpg', 'Pada hari apakah murid murid memetik gandum, sehingga orang farisi marah padanya ?', 'Sabat', 'pada hari sabat, orang farisi menganggap hari itu suci sehingga tidak boleh melakukan aktivitas apapun.', 16, '2025-12-23 21:50:45', '2025-12-23 21:50:45'),
(7, 1, 'questions/salomo.jpg', 'Siapa Raja yang berhikmat yang dapat memutuskan tindakan dalam perkara bayi pada dua perempuan?', 'Salomo', 'Salomo memiliki hikmat melebihi dari manusia sehingga dapat memutuskan tindakan dengan benar.', 16, '2025-12-23 21:50:45', '2025-12-23 21:50:45'),
(8, 1, 'questions/israel.jpg', 'Bangsa manakah yang disertai Tuhan untuk menghancurkan tembok Yerikho ?', 'Israel', 'Bangsa israel disertai Tuhan untuk menghancurkan tembok Yerikho dengan memutarinya selama 7 hari.', 16, '2025-12-23 21:50:45', '2025-12-23 21:50:45'),
(9, 1, 'questions/katak.jpg', 'Tulah ke berapa yang diberikan musa pada bangsa mesir untuk mendatangkan katak ?', 'Dua', 'Tulah kedua, musa menulahi bangsa mesir dengan katak agar raja firaun membebaskan bangsa israel dari perbudakan.', 16, '2025-12-23 21:50:45', '2025-12-23 21:50:45'),
(10, 1, 'questions/ketigamurid.jpg', 'Kepada siapa Tuhan Yesus memperlihatkan Musa dan Elia?', 'Petrus, Yakobus dan Yohanes', 'Salomo memiliki hikmat melebihi dari manusia sehingga dapat memutuskan tindakan dengan benar.', 16, '2025-12-23 21:50:45', '2025-12-23 21:50:45');
